import {moderationFloors} from './native-traces.js?v=46';
import {translateLegacy} from './legacy-entry.js?v=46';
import {store,pocket,url,asset,params,sourceBody,evidenceArticle,commandForm,mountPage,esc,owned,truth} from './arg-ui.js?v=46';
import {MATERIALS,SPRING_BV,AUTUMN_BV,EVIDENCE} from './arg-content.js?v=46';
import {searchGuidance} from './investigation.js?v=43';
const app=document.querySelector('#app');
if(location.hash){try{const legacy=translateLegacy(location.hash);if(legacy)location.replace(url(legacy.site,legacy.params));}catch{}}
const rows={'snapshot-index':['Q0325-07：引用副本留存说明','飞星'],notice:['【公告】发帖前看一下，附件请先遮姓名','飞星'],reports:['最近有三位同学查出幽门，整理一下就医经历','飞星'],lights:['三楼水房的灯终于换了','路过的人'],lost:['谁把蓝皮语文笔记落讲台上了','朱贵'],noodles:['周末补一下夜宵账，谁的车仔面还没给钱','杰哥'],printing:['周一帮忙打印的同学，材料记得领走','朱贵'],exam:['这次周测作文有人写完了吗','益达'],sports:['运动会旧照片还有几袋没人领','飞星'],leave:['补测登记：3月14日那场语文周测','啊水'],source:['关于第三张投稿，补一句','飞星'],chen:['关于那张报告，朱贵想说明几句','朱贵'],oldpost:['周五最后一首歌留给谁','小范不加班'],radio:['广播站：九月晚自习排期存档','电台值班']};
const aliases={'snapshot-index':['Q0325-07','Q0325','截图','屏蔽','快照','引用'],noodles:['夜宵','账单','值日','杰哥','316'],printing:['打印','委托','原图','朱贵','校刊'],exam:['语文','周测','作文'],sports:['旧照片','老照片','合照','运动会'],leave:['请假','缺考','补测'],source:['投稿','来源','匿名'],oldpost:['小范','值班','九月','广播'],radio:['排期','广播','末曲']};
function avatar(name){const i=[...name].reduce((a,c)=>a+c.charCodeAt(0),0)%6;return `<span class="arg-avatar" style="background-image:url('${asset('assets/avatars.png')}');background-position:${[0,50,100][i%3]}% ${i<3?0:100}%" aria-label="${esc(name)}的头像"></span>`;}
function floor(name,body,number=1){return `<article class="arg-floor"><aside>${avatar(name)}<b>${esc(name)}</b><small>${name==='飞星'?'巡视管理员 · LV.8':'高三学生 · LV.4'}</small><span>注册 2018-09</span></aside><section><header>${number}楼 <small>来自青禾校园网客户端</small></header><div class="arg-post-body">${body}</div><footer>点赞　回复　举报 <span>IP属地：校内</span></footer></section></article>`;}
function threadLink(id){return `<a href="${url('forum',{thread:id})}">${esc(rows[id]?.[0]||id)}</a>`;}
function home(q){let ids=['notice','reports','lights','lost'],guide;if(q){guide=searchGuidance(q);const word=guide.query.toLowerCase();ids=Object.keys(rows).filter(id=>(!['oldpost','radio','chen'].includes(id)||truth(store.get()).first)&&[rows[id][0],...(aliases[id]||[])].some(x=>x.toLowerCase().includes(word)||word.includes(x)));}
 app.innerHTML=`<div class="arg-bbs-crumb">青禾校园网 » 高三交流</div>${q?`<p>搜索“${esc(guide.query)}” · ${ids.length}项${guide.corrected?'（已纠正输入）':''}</p>`:'<div class="arg-forum-banner"><b>青禾论坛</b><span>学习 · 食堂 · 宿舍 · 闲聊</span></div><div class="arg-bbs-notice">学校不允许带手机，急事当面找人。历史主题请搜索。</div>'}<div class="arg-topics"><header>主题 / 标题 <span>作者</span></header>${ids.map(id=>`<article>${['notice','reports'].includes(id)?'<b class="arg-tag">置顶</b>':''}${threadLink(id)}<small>${rows[id][1]}　回复 ${id==='reports'?27:6}</small></article>`).join('')||'<p>没有匹配的主题。试试记得的事件名称。</p>'}</div>${q?'<p class="arg-subtle">相关说法：夜宵账单、周测作文、打印委托、旧照片。密保旧帖可按广播、值班检索。</p>':''}${truth(store.get()).first?`<p class="arg-new-post">新回复：${threadLink('chen')}</p>`:''}`;
}
function thread(id){if(!rows[id]){home('');return;}let body='',reply='';
 if(id==='reports'){body=`<div data-evidence="post"><p>前两份是by和乌鸡给的，第三张是私信投稿。先把就医经历放一起，有不确定的地方慢慢补。</p><p>不是三个人身份都核实了。别上来就问谁传给谁。</p></div><div class="arg-report-strip">${[['reportBy','A · by'],['reportWuji','B · 乌鸡'],['reportUnknown','C · 匿名投稿']].map(([key,label])=>`<a href="${url('forum',{view:'doc',id:key})}"><img src="${asset(EVIDENCE[key].image)}" alt="${label}报告"><span>${label}</span></a>`).join('')}</div><p>${threadLink('source')}　｜　<a href="${url('forum',{view:'compare'})}">把报告并排看</a></p>`;reply=`<p>别光猜夜宵了。摄影社春季接力那段，后面拍到学生会搬东西，视频号 <code>${SPRING_BV}</code>。</p><p><a href="${url('video',{bv:SPRING_BV})}">镜像缓存：3月14日下午的接力花絮</a>。上传日期晚了两天，现场时间看角落。</p><p>有人说请假去了医院，${threadLink('leave')}里留着当时怎么说的。</p><p>杰哥说查吃了什么可以<a href="${url('canteen',{view:'card'})}">去食堂一卡通查凭条</a>，他把查询便笺也给了by。</p><p>益达的笔记、照片袋和旧账号？<a href="${url('pan',{folder:'accounts'})}">他们自愿提供的资料目录在这里</a>，不要搬别人私事。</p>`;}
 else if(id==='lights'){const p=MATERIALS.posts.find(x=>x.id===id);body=sourceBody(p.body);reply=evidenceArticle('clockNote',{compact:true});}
 else if(id==='lost'){const p=MATERIALS.posts.find(x=>x.id===id);body=sourceBody(p.body);reply='<p>蓝本最后夹着一张《禾声》领稿条，写的是第16期本周校对，第17期只是下一期样张。飞星在边上又写了句“别看预告填本期”。谁的快拿走，别又说是益达那本。</p>';}
 else if(id==='snapshot-index')body=`<p>有人问被屏蔽那两楼还能不能核对。原帖暂时屏蔽前，我在25号存过7楼的引用，副本编号Q0325-07。28号原作者又撤回过一次，别把这几件事混成一次删帖。</p><p>副本不带账号实名，也不转贴别人的整段私信。</p><p><a href="${url('pan',{folder:'snapshots'})}">Q0325-07 / 本人留存的只读副本</a></p>`;
 else if(id==='printing'){body=evidenceArticle('printing',{compact:true})+sourceBody(MATERIALS.posts.find(p=>p.id==='printing').body)+`<p>《禾声》试印登记：第16期校对至3月23日，第17期是3月24日之后的预告。收稿页留在<a href="${url('pan',{folder:'heshe'})}">校刊阅览资料夹</a>。</p>`;}
 else if(id==='leave')body=evidenceArticle('leaveClaim',{compact:true})+`<p>补测通知按月日加开考时间保护：3月28日14:30。<a href="${url('pan',{folder:'makeup'})}">班级通知副本</a></p>`;
 else if(id==='source')body=evidenceArticle('source',{compact:true})+`<p>原始投稿放进了<a href="${url('pan',{folder:'heshe'})}">校刊阅览夹</a>。请对收到时的原件，不要只看转发截图。</p>`;
 else if(id==='chen'){const t=truth(store.get());if(t.first)body=`<p>“那天我没有去做检查。”朱贵说。周测没准备好，他先躲去了学生会，帮阉鸡把那台老打印机搬上楼，后来把“请假”说成了“医院查出幽门”。</p><p>你3月17日请他打印，他拿到了原图。补交材料时改了日期；飞星征稿后又把图投了过去。他以为混在几份匿名经历里，别人就不会再问那场考试。</p><p>“在操场拍到我，只能说明我在那里。”他说，“那张图是我改的，这个我认。”</p><p>你没有替他说算了。缺考、假材料和匿名暗示，都要由他自己说明白；这也没有证明益达传染过谁。</p><p>走之前他又提了一件事：去医务室补材料时，垃圾桶里露出半张写着复查的单子，有人问怎么没登记，后来就被收走了。“我不知道是谁的。你们要问这个，可以找小范，她已经不在医务室了。”</p><p><a href="${url('pan',{folder:'clinic'})}">小范交给飞星的阅览授权与副本目录 →</a></p>`;else body=`<p>远景只能说明有人搬设备。要追问改图，仍需原始投稿、原图接触、报告本身和请假说法互相印证。</p><button type="button" data-confront>拿已核对的材料问朱贵</button><p data-response></p>`;}
 else if(['oldpost','radio'].includes(id))body=evidenceArticle(id,{compact:true});
 else if(id==='notice')body='<p>发帖不要放没遮姓名的完整病历。好好说话，没核实的事别替别人盖章。旧主题可以搜索，附件仍按原来的授权范围查。</p>';
 else {const p=MATERIALS.posts.find(x=>x.id===id);body=p?sourceBody(p.body):'<p>本子先放讲台左边，谁的周一来拿。</p>';if(id==='sports')body+=`<p>秋季花絮另在<a href="${url('video',{bv:AUTUMN_BV})}">${AUTUMN_BV}</a>。它是上一年拍的，别和三月那段混了。</p>`;if(id==='exam')body+=`<p>${threadLink('leave')}　｜　<a href="${url('forum',{view:'doc',id:'diary'})}">益达借来的记录</a></p>`;}
 app.innerHTML=`<div class="arg-bbs-crumb"><a href="index.html">青禾论坛</a> » ${esc(rows[id][0])}</div><h1 class="arg-thread-title">${esc(rows[id][0])}</h1>${floor(rows[id][1],body)}${reply?floor('隔壁排队的',reply,2):''}${id==='reports'?'<p class="arg-folded-replies">3、4楼日常回复已折叠</p>'+floor('杰哥',evidenceArticle('screenMemory',{compact:true}),5)+moderationFloors(floor):''}<div class="arg-thread-links">${threadLink('printing')}　${threadLink('leave')}　${threadLink('chen')}</div>`;app.querySelector('[data-confront]')?.addEventListener('click',()=>pocket.feedback(store.dispatch('confront').message));
}
function compare(){app.innerHTML=`<h1>报告附件对照</h1><p>项目模板、印章和设备噪点可能重复。选择能够具体对齐的纸面痕迹。</p><div class="arg-compare-tools"><button type="button" data-report-mode="side">并排看</button><button type="button" data-report-mode="overlay">叠图核对</button><label>叠图透明度<input type="range" min="0" max="100" value="50" data-report-opacity></label></div><div class="arg-compare" data-compare-side>${['reportBy','reportUnknown'].map(id=>`<figure data-evidence="${id}"><img src="${asset(EVIDENCE[id].image)}" alt="${esc(EVIDENCE[id].title)}"><figcaption>${esc(EVIDENCE[id].title)}</figcaption></figure>`).join('')}</div><div class="arg-compare-overlay" hidden><img src="${asset(EVIDENCE.reportBy.image)}" alt="报告A底图"><img data-overlay-report src="${asset(EVIDENCE.reportUnknown.image)}" alt="报告C叠图" style="opacity:.5"></div><p>还需<a href="${url('pan',{folder:'heshe',file:'submission'})}">核对飞星收稿时的原始附件</a>。</p><form id="compareForm"><div class="arg-check-grid">${[['stamp','红章角度'],['fold','左下折痕的转弯'],['noise','打印灰点'],['circle','蓝圈右侧的缺口'],['template','检测项目版式'],['positive','都写着阳性']].map(([key,text])=>`<label><input type="checkbox" name="marks" value="${key}">${text}</label>`).join('')}</div><button>记录图像质疑</button><p data-response role="status"></p></form><p>${threadLink('chen')}</p>`;commandForm(document.querySelector('#compareForm'),'compare',d=>({marks:d.getAll('marks')}));app.querySelectorAll('[data-report-mode]').forEach(b=>b.onclick=()=>{const overlay=b.dataset.reportMode==='overlay';app.querySelector('[data-compare-side]').hidden=overlay;app.querySelector('.arg-compare-overlay').hidden=!overlay;});app.querySelector('[data-report-opacity]').oninput=e=>app.querySelector('[data-overlay-report]').style.opacity=Number(e.target.value)/100;}
mountPage(()=>{const p=params();if(p.get('view')==='compare')compare();else if(p.get('view')==='doc')app.innerHTML=evidenceArticle(p.get('id'));else if(p.has('thread'))thread(p.get('thread'));else home(p.get('q')||'');});
